        return base64.urlsafe_b64decode(payload['body']['data']).decode('utf-8',errors='replace')
    if 'parts' in payload:
        for p in payload['parts']:
            r = get_body(p)
            if r: return r
    return ''
body = get_body(d.get('payload',{}))
print(body[:3000])
